<script setup lang="ts">
import {acquireInert} from "../services/inertLease"
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import type {NoteEntity} from '@note-flow/core'
import type {FolderEntity} from '@note-flow/core/contracts'
import {folderConsolidationCandidates,groupFolderConsolidation} from '../services/folderConsolidation'
const props=defineProps<{folder:FolderEntity;folders:FolderEntity[];notes:NoteEntity[];busy?:boolean;error?:string}>(),emit=defineEmits<{close:[];select:[uids:string[]]}>()
const includeChildren=ref(true),mode=ref<'title'|'folder'|'all'>('title'),selected=ref(new Set<string>()),message=ref(''),limit=ref(100),groupLimit=ref(30),query=ref(''),host=ref<HTMLElement>()
const candidates=computed(()=>folderConsolidationCandidates(props.folder,props.folders,props.notes,includeChildren.value)),groups=computed(()=>groupFolderConsolidation(candidates.value.filter(note=>!query.value.trim()||note.title.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())),mode.value,props.folders))
watch(candidates,rows=>{const allowed=new Set(rows.map(row=>row.uid));selected.value=new Set([...selected.value].filter(uid=>allowed.has(uid)))})
let origin:HTMLElement|null=null,root:HTMLElement|null=null,releaseInert=()=>{}
onMounted(async()=>{origin=document.activeElement as HTMLElement;root=document.querySelector('#app');releaseInert=acquireInert(root);await nextTick();host.value?.querySelector<HTMLButtonElement>('button')?.focus()})
onBeforeUnmount(()=>{releaseInert();origin?.isConnected&&origin.focus({preventScroll:true})})
function trap(event:KeyboardEvent){if(event.key!=='Tab')return;const nodes=[...host.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled)')||[]],first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
function toggle(uids:string[],checked:boolean){const next=new Set(selected.value);for(const uid of uids)checked?next.add(uid):next.delete(uid);if(next.size>20){message.value='每次最多选择 20 篇，请分批整合';return}selected.value=next;message.value=''}
</script>
<template><Teleport to="body"><div class="folder-plan-backdrop" @click.self="!busy&&emit('close')"><section ref="host" class="folder-plan" @keydown="trap" role="dialog" aria-modal="true" aria-label="目录笔记整合预览" @keydown.esc.stop="!busy&&emit('close')"><header><h2>整合目录笔记 · {{folder.name}}</h2><button :disabled="busy" @click="emit('close')">关闭</button></header><p>先分组、选择，再进入 AI 整合审阅。展示本机已加载的普通笔记，未同步内容请先同步。分组仅供选择，不判断语义重复，也不会修改原笔记。</p><div class="folder-plan-controls"><label><input v-model="includeChildren" type="checkbox" :disabled="busy"/>包含子目录</label><label>分组<select v-model="mode" :disabled="busy"><option value="title">标题开头</option><option value="folder">所在目录</option><option value="all">不分组</option></select></label><input v-model="query" placeholder="筛选笔记标题" :disabled="busy"/><span>可选 {{candidates.length}} 篇 · 已选 {{selected.size}} / 20</span></div><p v-if="!candidates.length">没有可整合的普通笔记。文件、图片、归档及禁止 AI 处理的笔记不会列入。</p><div class="folder-plan-list"><article v-for="group in groups.slice(0,groupLimit)" :key="group.label"><header><strong>{{group.label}} · {{group.notes.length}}</strong><button :disabled="busy" @click="toggle(group.notes.map(note=>note.uid),!group.notes.every(note=>selected.has(note.uid)))">{{group.notes.every(note=>selected.has(note.uid))?'取消本组':'选择本组'}}</button></header><label v-for="note in group.notes.slice(0,limit)" :key="note.uid"><input type="checkbox" :checked="selected.has(note.uid)" :disabled="busy" @change="toggle([note.uid],($event.target as HTMLInputElement).checked)"/><span>{{note.title||'未命名笔记'}}</span></label><button v-if="group.notes.length>limit" @click="limit+=100">显示更多</button></article><button v-if="groups.length>groupLimit" @click="groupLimit+=30">显示更多分组</button></div><p v-if="message||error" role="alert">{{error||message}}</p><footer><button :disabled="busy" @click="selected=new Set()">清空选择</button><button :disabled="busy||selected.size<2" @click="emit('select',[...selected])">{{busy?'核对来源…':'进入整合审阅'}}</button></footer></section></div></Teleport></template>
<style scoped>.folder-plan-backdrop{position:fixed;inset:0;z-index:1800;background:#14271d55;display:grid;place-items:center;padding:20px}.folder-plan{display:flex;flex-direction:column;gap:12px;width:min(700px,100%);max-height:calc(100vh - 40px);padding:20px;border-radius:12px;background:#fff;box-sizing:border-box;color:var(--pc-text)}.folder-plan h2{font-size:17px;margin:0}.folder-plan header,.folder-plan footer,.folder-plan-controls{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.folder-plan p{font-size:12px;line-height:1.7;margin:0;color:var(--pc-muted)}.folder-plan-controls{font-size:12px}.folder-plan button,.folder-plan select{padding:6px 10px;border:1px solid var(--pc-border);border-radius:6px;background:#fff;color:inherit;font:inherit;font-size:12px;cursor:pointer}.folder-plan-list{overflow:auto;min-height:0;flex:1}.folder-plan-list article{padding:10px 0;border-top:1px solid var(--pc-border)}.folder-plan-list strong{font-size:12px}.folder-plan-list label{display:flex;gap:8px;align-items:center;padding:7px 0;font-size:12px}.folder-plan-list label span{overflow-wrap:anywhere;min-width:0}.folder-plan footer{padding-top:10px;border-top:1px solid var(--pc-border)}</style>
